//! Santabolsa.com "System Tester" MetaStock formulas (Acrobat capture of www.santabolsa.com/formumeta/,
//! 2002; research drive MetaStock/@Systems & Indicators/Santabolsa - Formulas,Sistemas...para Mestastock/
//! Santabolsa.pdf, 30 pp.). Book id `mssta`. Every system printed on the System Tester page (pp.3-20) is
//! catalogued with its printed rules; each one is a duplicate of a vault entry (dgmf / mstt) or of the Libanes
//! collection (mslib, which prints the same formulas with the author's test settings), or is not testable, so
//! none is re-implemented here. Page refs = PDF page. Checks: library/mssta/.
use crate::books::msws::{Book, Exec, Sys, EXEC_DEFAULT};
use crate::connors::{Ctx, ParamDef, Params, StrategyDef, Trade};
#[allow(unused_imports)]
use crate::connors::Status::{Live, NeedsData, NotTestable};
use std::sync::OnceLock;

pub const BOOK: &str = "mssta";
const CONV: &str = "Catalogue only (see status).";
pub static MSSTA: Book = Book { id: BOOK, sys: SYS, fml: &[], conv: CONV, cat: OnceLock::new(), par: OnceLock::new() };
pub fn catalogue() -> Vec<StrategyDef> { MSSTA.catalogue() }
pub fn params(id: &str) -> Option<Vec<ParamDef>> { MSSTA.params(id) }
pub fn run(id: &str, x: &Ctx, from: usize, to: usize, p: &Params) -> Option<Vec<Trade>> { MSSTA.run(id, x, from, to, p) }
pub fn family_of(id: &str) -> Option<(&'static str, &'static str, &'static str)> { MSSTA.family_of(id) }
#[allow(dead_code)]
fn _exec_type_check(e: Exec) -> Exec { e }

